#include <stdio.h>

int main(void) {
    unsigned int x = 0x01020304;
    unsigned char *p = (unsigned char*)&x;
    if (p[0] == 0x04) printf("little-endian\n");
    else if (p[0] == 0x01) printf("big-endian\n");
    else printf("unknown\n");
    printf("bytes: %02X %02X %02X %02X\n", p[0], p[1], p[2], p[3]);
    return 0;
}
